insert into usage_record(
    user_id, lab_id, person, resource, scene, use_time, status, remark, source_type, source_id
)
values(
    #{userId}, #{labId}, #{person}, #{resource}, #{scene}, #{useTime}, #{status}, #{remark},
    #{sourceType}, #{sourceId}
)

mapper.select:
select min(id)
from (
    select id from lab where lab_name = #{resource}
    union all
    select id from lab where lab_code = #{resource}
) matches
having count(distinct id) = 1
